import React from 'react';
import { isElement } from 'react-is';

import {
  EmptyStateSlotProps,
  EmptyStateSlot,
} from '../../../slots/chart-states/EmptyStateSlot.js';
import {
  ErrorStateSlotProps,
  ErrorStateSlot,
} from '../../../slots/chart-states/ErrorStateSlot.js';

export function getChartStatesTemplates(children: React.ReactNode) {
  let emptyState: EmptyStateSlotProps['children'] | undefined,
    errorState: ErrorStateSlotProps['children'] | undefined;

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case EmptyStateSlot: {
          emptyState = child.props.children;

          break;
        }

        case ErrorStateSlot: {
          errorState = child.props.children;

          break;
        }
      }
    }
  });

  return { emptyState, errorState };
}
